#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.34490098, -0.234243005, -0.017180645], 'basis': [[0.2438822720167358, 0.18337370424502752, 0.9523106226370743], [0.0, 0.9819610899466771, -0.18908309768653075], [-0.9698048450054035, 0.046114015463753516, 0.23948290164822586]], 'axis': [0.9523106226370743, -0.18908309768653075, 0.23948290164822586], 'zmin': -0.056835477970122554, 'zmax': 0.04729459893794498, 'profiles': [{'outer': [[-0.0956265046905102, -0.026904369372093607], [-0.098621329983368, -0.017655012970571378], [-0.09907865960687942, -0.008351729985483482], [-0.09658368628420001, 0.0003346495010042715], [-0.09613016833969301, 0.0014820565741816975], [-0.09082167542521613, 0.010054944688542717], [-0.08347455013716074, 0.017321441050850435], [-0.0750483609163177, 0.02260161388462857], [-0.06653875191094523, 0.02546221890885511], [-0.05816394104489849, 0.02725965251838165], [-0.050299291854238516, 0.02967152288777892], [-0.043769070102463434, 0.034878496733047146], [-0.03928855851097645, 0.04428972748671078], [-0.03656689596955852, 0.05618214385005869], [-0.035131449749429874, 0.06827357387641488], [-0.03373060551392591, 0.0868005120573701], [-0.03311033726756962, 0.09220281643145939], [-0.03234508372254479, 0.09555510897569132], [-0.031264903634593166, 0.09750742458232729], [-0.02977245226473411, 0.09843822103889138], [-0.02791622961050873, 0.09874265970407442], [-0.020053655321578604, 0.09813588542787016], [-0.008544256606839109, 0.09633793846572858], [0.007736681029201434, 0.09327935742005455], [0.026277203110872872, 0.08947329536973475], [0.043814040632443436, 0.08556667090220778], [0.05739951680310196, 0.08226018312357965], [0.06646527774498112, 0.07948042134491158], [0.06799463436462144, 0.0785126566833765], [0.06889265221042165, 0.07710368823374764], [0.06936141621909027, 0.07608800581647521], [0.0694578553543133, 0.07394203569265487], [0.06857146860964408, 0.07056589194454312], [0.06645929743020469, 0.06548985837191366], [0.05818129483150653, 0.04827209842858407], [0.05315599763060356, 0.036675000332706986], [0.04946513518505367, 0.024542640416518813], [0.04867404198284356, 0.013607888961468976], [0.052105250098978546, 0.005281368465586135], [0.058557688444721895, -0.0011461449592121413], [0.07515060996610162, -0.013165040705823201], [0.08353159118621302, -0.02072560750089138], [0.09032309705385283, -0.029408906756611255], [0.09114872934258855, -0.03070110306091548], [0.09441960288888225, -0.03962660156315864], [0.0934931558513447, -0.04880409416616062], [0.08804424276576854, -0.058289203046411095], [0.07910143269277099, -0.06734228492776545], [0.07768453655599977, -0.06855000082027704], [0.06654586115753937, -0.07597538461957694], [0.05585691554794661, -0.08010203436624665], [0.04713429178983816, -0.08006920675448147], [0.04034165751567834, -0.0765529281849477], [0.035030107944722486, -0.0707699641950622], [0.03085977975558134, -0.06421688745085787], [0.026388065157884135, -0.05606518675532862], [0.02368877843168971, -0.051795869373673434], [0.022119031090621775, -0.05014900658801522], [0.021847845314433248, -0.05007407259700088], [0.0213792928517067, -0.05153302372030371], [0.021411646073653343, -0.054285978299996235], [0.021924680040706836, -0.05816657852636561], [0.022939562212238244, -0.0648528781564113], [0.023663345379912538, -0.07240953710466666], [0.023526576582457444, -0.08027966488210735], [0.021813336921318337, -0.08772154625894335], [0.017904843666398183, -0.0940472992474829], [0.011097141684542951, -0.09869226426779551], [0.001123216800700214, -0.10127050047742515], [-0.010621814369990996, -0.10162236602595437], [-0.02245137212578174, -0.09980894375178971], [-0.03254558081291863, -0.09566182253064243], [-0.03948493570354583, -0.08939620613465096], [-0.04356024936039767, -0.08135222604041459], [-0.04535373198530195, -0.07214084417983221], [-0.045459528222372036, -0.06263795699903896], [-0.04448428272378423, -0.053767628489943826], [-0.04313250870027458, -0.04592783667981306], [-0.04213344768500342, -0.039573536510870144], [-0.0422769961866247, -0.035707254645768176], [-0.04415875509963836, -0.03510525033748906], [-0.047450426412815105, -0.03693881351252823], [-0.0516897707456607, -0.04007174762759545], [-0.05685157469112315, -0.043337293456221865], [-0.06297153716462152, -0.04581044122580787], [-0.06972168805603551, -0.04680007327734123], [-0.07655580983654736, -0.04579217808454663], [-0.08324320844728422, -0.042277008464037105], [-0.0846359380435949, -0.040996846243681426], [-0.0906052046698188, -0.03506190830849994]], 'holes': []}], 'simplify_tolerance': 4.007300514600576e-05, 'sketch_entity_count': 102}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
